tool_input.command:
cat >> db/schema.ts <<'EOF'

export const tags = sqliteTable("tags", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull().unique(),
});

export const postTags = sqliteTable(
  "post_tags",
  {
    postId: integer("post_id").notNull(),
    tagId: integer("tag_id").notNull(),
  },
  (t) => [primaryKey({ columns: [t.postId, t.tagId] })],
);
EOF
sed -i '' 's/import { integer, sqliteTable, text }/import { integer, primaryKey, sqliteTable, text }/' db/schema.ts
env CI=1 pnpm exec void db generate 2>&1 | tail -8; git status --short; grep -n "inArray" node_modules/void/dist/db* -r | head -2
